import{_ as r,o as t,c as a,a2 as s}from"./chunks/framework.BxGh02fV.js";const m=JSON.parse('{"title":"Premier lancement","description":"","frontmatter":{"title":"Premier lancement"},"headers":[],"relativePath":"guide/first-run.md","filePath":"guide/first-run.md"}'),n={name:"guide/first-run.md"};function o(i,e,l,u,p,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h1><p>Au tout premier lancement, Effortless ne connaît pas encore votre identité. Avant de vous montrer le sélecteur de workspace, il vous fait passer par un court assistant : votre profil, le déploiement d&#39;Effortless dans vos outils IA, puis votre premier workspace.</p><h2 id="l-ecran-de-demarrage" tabindex="-1">L&#39;écran de démarrage <a class="header-anchor" href="#l-ecran-de-demarrage" aria-label="Permalink to &quot;L&#39;écran de démarrage&quot;">​</a></h2><p>À chaque lancement, la mascotte s&#39;affiche un court instant pendant que l&#39;application charge votre profil, puis s&#39;efface en fondu. Ensuite :</p><ul><li>si vous avez déjà un profil, vous arrivez sur le sélecteur (<a href="/Effortless/guide/start.html">Ouvrir un workspace</a>) ;</li><li>sinon, l&#39;assistant de premier lancement s&#39;ouvre.</li></ul><h2 id="l-assistant-de-premier-lancement" tabindex="-1">L&#39;assistant de premier lancement <a class="header-anchor" href="#l-assistant-de-premier-lancement" aria-label="Permalink to &quot;L&#39;assistant de premier lancement&quot;">​</a></h2><p>En haut, quatre pastilles numérotées montrent où vous en êtes. En bas, <strong>Précédent</strong> revient à l&#39;étape d&#39;avant ; <strong>Suivant</strong> avance ; <strong>Plus tard</strong> passe une étape facultative.</p><h3 id="_1-bienvenue" tabindex="-1">1. Bienvenue <a class="header-anchor" href="#_1-bienvenue" aria-label="Permalink to &quot;1. Bienvenue&quot;">​</a></h3><p>« Bienvenue dans Effortless » présente l&#39;application et rappelle que tout reste sur votre machine (<code>~/.effortless</code>). Cliquez sur <strong>Commencer</strong>.</p><h3 id="_2-creer-votre-profil" tabindex="-1">2. Créer votre profil <a class="header-anchor" href="#_2-creer-votre-profil" aria-label="Permalink to &quot;2. Créer votre profil&quot;">​</a></h3><p>Une identité locale, sans compte. Elle signe vos décisions, vos specs et vos commits.</p><ul><li><strong>Nom</strong> : obligatoire.</li><li><strong>E-mail</strong> : obligatoire ici, au format <code>nom@domaine.dev</code>.</li><li><strong>Auteur par défaut</strong> : obligatoire, « la signature de votre travail ».</li></ul><p>L&#39;encadré <strong>Votre signature</strong> montre en aperçu comment votre nom apparaîtra, par exemple sur une décision. Cette étape ne se passe pas : <strong>Suivant</strong> reste grisé tant que le nom, l&#39;e-mail et l&#39;auteur ne sont pas valides, et c&#39;est lui qui enregistre le profil.</p><h3 id="_3-deployer-effortless-dans-tes-outils" tabindex="-1">3. Déployer Effortless dans tes outils <a class="header-anchor" href="#_3-deployer-effortless-dans-tes-outils" aria-label="Permalink to &quot;3. Déployer Effortless dans tes outils&quot;">​</a></h3><p>Cette étape installe le serveur MCP d&#39;Effortless et ses skills dans les assistants IA détectés sur votre poste (Claude Code, opencode…). C&#39;est le même panneau que <strong>Préférences</strong> › <strong>MCP &amp; Skills</strong> : sélectionnez les assistants, puis <strong>Déployer</strong>. Voir <a href="/Effortless/guide/preferences.html">Profil et préférences</a>.</p><p>Si une ancienne installation est détectée, un bandeau « Installation legacy détectée » propose de la migrer.</p><p>Vous pouvez passer cette étape avec <strong>Plus tard</strong> et déployer depuis les préférences quand vous voulez.</p><h3 id="_4-ton-premier-workspace" tabindex="-1">4. Ton premier workspace <a class="header-anchor" href="#_4-ton-premier-workspace" aria-label="Permalink to &quot;4. Ton premier workspace&quot;">​</a></h3><p>Un workspace est un projet Effortless.</p><ul><li><strong>Ouvrir un dossier…</strong> : choisissez un dossier qui contient déjà un projet Effortless ;</li><li><strong>Créer un workspace…</strong> : choisissez un dossier, Effortless l&#39;initialise.</li></ul><p>Dans les deux cas, le workspace s&#39;ouvre dans un onglet et l&#39;assistant se ferme. <strong>Terminer</strong> (ou <strong>Plus tard</strong>) ferme l&#39;assistant sans rien ouvrir : vous arrivez alors sur le sélecteur.</p><h2 id="rejouer-l-introduction" tabindex="-1">Rejouer l&#39;introduction <a class="header-anchor" href="#rejouer-l-introduction" aria-label="Permalink to &quot;Rejouer l&#39;introduction&quot;">​</a></h2><p><strong>Préférences</strong> › <strong>Prise en main</strong> › <strong>Relancer l&#39;introduction</strong> rejoue l&#39;assistant. Votre profil existe déjà : l&#39;étape d&#39;identité est alors préremplie.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>L&#39;agent n&#39;a pas d&#39;assistant de premier lancement. <code>effortless_deploy</code> fait le travail de l&#39;étape 3, et <code>effortless_init</code> crée un workspace.</p>',25)])])}const f=r(n,[["render",o]]);export{m as __pageData,f as default};
